const box = document.querySelector(".search");
let timer = null;

box.addEventListener("input", () => {
  clearTimeout(timer);
  timer = setTimeout(() => {
    console.log(`Searching for ${box.value}`);
  }, 300);
});

const marker = document.querySelector(".load-more");

const observer = new IntersectionObserver((entries) => {
  for (const entry of entries) {
    console.log(`Marker on screen: ${entry.isIntersecting}`);
  }
});

observer.observe(marker);

const worker = new Worker("primes-worker.js", { type: "module" });

worker.addEventListener("message", (event) => {
  console.log(`Primes below 5000000: ${event.data}`);
});

worker.postMessage(5000000);
console.log("Counting in the background. The page still responds.");
